# v1: v0 plus a Vesper/Heart/Marcella/Vendetta/Ryth draft chain, safer tribute altars
# (away from monoliths), retreat when hurt and in danger, and backing off from
# unfavourable local fights.

# ---- tunable constants (as literals) ----
# fight only when local_strength(4) >= 0.7 or health is high
# retreat to spawn when in_danger() and health < 35%
# recall at 20% health, or at 50% when carrying gems

def safe_altars():
    return minus( minus( altars(), locked_altars() ), ring( monolith_tiles(), 5 ) )

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
