# v1: fs-1 base plus (a) a draft chain (Vesper Vale, Heart of Ruin, Marcella, Vendetta, Ryth),
# (b) focus fire on the weakest enemy in range, (c) recall when a local fight is lost,
# (d) gem carriers prefer altars outside the monster-reach ring of monoliths.

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_marcella()):
