    buy(shard(stat_health()), shards_bought - strength_shards)
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat at 20% health normally, at 50% when carrying gems
let low_health = health() < 0.2 * max_health()
let carrying_hurt = gems() > 0 and health() < 0.5 * max_health()
if not at_spawn and (low_health or carrying_hurt):
    recall()
    end_turn()

# losing a local fight: pull out instead of feeding kills
if not at_spawn and enemies_within(4) > 0 and local_strength(4) < 0.7:
    recall()
    end_turn()

# fight: focus the weakest enemy in range
let enemy = weakest(filter(enemies_visible(), in_attack_range()))
if exists(enemy):
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
