# bigger gem bags (tribute early when hurt/threatened), never filter locked altars (tribute attacks the lock),
# prefer altars away from monoliths, skip monolith/golem camps, focus the weakest enemy in range.

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_heart_of_ruin()):
        pick(champ_heart_of_ruin())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_vendetta()):
        pick(champ_vendetta())
    elif available(pool, champ_ryth()):
        pick(champ_ryth())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_stellar()):
        pick(champ_stellar())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep all_altars = altars()
keep safe_altar_ring = ring( minus( all_altars, ring(monolith_tiles(), 5) ), 1 )
keep all_altar_ring = ring( all_altars, 1 )
keep easy_goals = minus( camp_spawns, union( monolith_tiles(), golem_tiles() ) )

# tunable constants
let RECALL_HP = 0.35
let CARRY_RECALL_HP = 0.5
let BAG = 20
let EARLY_TRIBUTE_HP = 0.6
let TREASURE_UNTIL = 500

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let hp = health() / max_health()
let at_spawn = contains( spawn_region(ally()), position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    if shards_bought > 0:
        if round_number() < TREASURE_UNTIL:
            buy( shard_of(family_treasure(), stat_strength()), shards_bought )
        else:
            let strength_shards = floor( shards_bought / 2 )
            buy( shard_of(family_bruiser(), stat_strength()), strength_shards )
            buy( shard_of(family_bruiser(), stat_health()), shards_bought - strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if hp < 1 and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# low health: get out of danger first (recall is cancelled by damage), then recall
if not at_spawn and (hp < RECALL_HP or (gems() > 0 and hp < CARRY_RECALL_HP)):
    if in_danger():
        move_towards( closest( spawn_region(ally()) ) )
        end_turn()
    recall()
    end_turn()

let enemy = weakest( filter( enemies_visible(), in_attack_range() ) )
if exists(enemy):
    set_team_target(enemy)
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

# tribute with a real bag, or early when hurt / threatened / near the end
if gems() >= BAG or (gems() > 0 and (hp < EARLY_TRIBUTE_HP or enemies_within(6) > 0 or round_number() > 1900)):
    let altar = first( filter( all_altars, within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    let target = closest( safe_altar_ring )
    if exists(target):
        move_towards(target)
        end_turn()
    move_towards( closest( all_altar_ring ) )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = weakest( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus( easy_goals, respawning_visible_spawns() )

# already standing on a cleared camp spawn: hold here so the capture timer keeps running
if contains(goals, position()):
    end_turn()

let goal = closest(goals)
if exists(goal):
    move_towards(goal)
else:
    if gems() > 0:
        move_towards( closest( all_altar_ring ) )
    else:
        move_towards( closest( camp_spawns ) )
let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()
